package com.sigtm.backend.controller; import com.sigtm.backend.service.ReporteComprasService; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reportes/compras") @RequiredArgsConstructor public class ReporteComprasController {private final ReporteComprasService service; @GetMapping("/resumen") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<Map<String,Object>> resumen(){return ResponseEntity.ok(service.resumen());} @GetMapping("/proveedores") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<List<Map<String,Object>>> proveedores(){return ResponseEntity.ok(service.porProveedor());} @GetMapping("/vencimientos") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<?> vencimientos(@RequestParam(defaultValue="14") int dias){return ResponseEntity.ok(service.alertasVencimiento(dias));} @GetMapping("/costos") @PreAuthorize("hasAuthority('COMPRAS:VER')") public ResponseEntity<?> costos(){return ResponseEntity.ok(service.tendencias());}}
